-- Garante disciplinas de Direito base (idempotente).
on conflict (slug) do update set name=excluded.name, description=excluded.description, icon=excluded.icon, sort_order=excluded.sort_order;

-- Garante colunas de banca/concurso (idempotente).
alter table public.questions add column if not exists banca text;
alter table public.questions add column if not exists concurso text;
create index if not exists questions_banca_concurso_idx on public.questions (banca, concurso);

-- Questoes autorais adicionais de Direito (lote 3).
-- Conteudo inedito para treino; sem referencia a obras ou provas oficiais.

on conflict (source_ref) do update set
  subject_id=excluded.subject_id, prompt=excluded.prompt, options=excluded.options,
  correct_index=excluded.correct_index, explanation=excluded.explanation,
  difficulty=excluded.difficulty, topic=excluded.topic, question_type=excluded.question_type,
  status=excluded.status, sort_order=excluded.sort_order, banca=excluded.banca, concurso=excluded.concurso;