insert into public.questions (subject_id, source_ref, prompt, options, correct_index, explanation, difficulty, topic, question_type, status, sort_order, banca, concurso)
values
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-081', 'Um bem publico de uso comum do povo, como uma praca, em regra:', '["Pode ser alienado livremente pelo municipio.","E de uso exclusivo da administracao.","Pode ser utilizado por todos, mas sua alienacao exige desafetacao previa.","E considerado bem privado do Estado.","Nao pode ser objeto de servidao."]'::jsonb, 2, 'Bens de uso comum do povo sao destinados a utilizacao geral e nao podem ser alienados sem o procedimento de desafetacao que os desvincule da finalidade publica.', 'medium', 'Bens publicos', 'multiple_choice', 'published', 5150, 'FCC', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-082', 'A improbidade administrativa praticada com dolo ou culpa que cause prejuizo ao erario pode resultar, entre outras consequencias:', '["Apenas advertencia administrativa.","Condenacao a ressarcimento integral do dano, perda da funcao publica e suspensao dos direitos politicos, conforme o caso.","Impossibilidade de acao civil, reservada ao Ministerio Publico.","Prescricao automatica em 30 dias.","Transferencia do agente para outro orgao."]'::jsonb, 1, 'A lei de improbidade preve sancoes que incluem ressarcimento, perda da funcao publica, suspensao dos direitos politicos e multa civil, conforme a gravidade e o dolo ou culpa.', 'medium', 'Improbidade administrativa', 'multiple_choice', 'published', 5151, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-083', 'Em licitacao, o principio da isonomia exige, entre outros aspectos:', '["Tratamento diferenciado conforme a origem do licitante.","Divulgacao do edital e oportunidade igual de participacao aos interessados.","Preferencia automatica a empresas locais.","Sigilo das propostas ate a assinatura do contrato.","Dispensa de publicacao em qualquer hipotese."]'::jsonb, 1, 'A isonomia na licitacao assegura igualdade de condicoes aos licitantes, com publicidade do edital e regras objetivas de participacao.', 'medium', 'Licitacoes, convenios e contratos', 'multiple_choice', 'published', 5152, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-084', 'A concessao de servico publico, em regra, exige:', '["Contrato administrativo precedido de licitacao, salvo as hipoteses legais de dispensa ou inexigibilidade.","Autorizacao oral do chefe do executivo.","Apenas publicacao em jornal local.","Transferencia gratuita da titularidade ao particular.","Inexistencia de regulamento."]'::jsonb, 0, 'A concessao de servico publico e formalizada por contrato administrativo, em regra precedido de licitacao, observadas as excecoes legais.', 'medium', 'Servicos publicos', 'multiple_choice', 'published', 5153, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-085', 'Como regra constitucional, a investidura em cargo publico depende de:', '["Indicacao politica em qualquer caso.","Aprovacao em concurso publico, ressalvados os cargos em comissao previstos em lei.","Autorizacao judicial previa.","Contrato privado com o orgao.","Eleicao pelos servidores."]'::jsonb, 1, 'O art. 37, II, da Constituicao exige concurso publico como regra, ressalvados os cargos em comissao declarados em lei.', 'easy', 'Servidores publicos', 'multiple_choice', 'published', 5154, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-086', 'A desapropriacao por utilidade publica exige, em regra:', '["Pagamento posterior, sem necessidade de justa indenizacao previa.","Justa e previa indenizacao em dinheiro, ressalvadas as hipoteses legais de deposito previo.","Autorizacao do Poder Legislativo em cada caso.","Concordancia do proprietario, em qualquer situacao.","Inexistencia de processo administrativo."]'::jsonb, 1, 'A Constituicao assegura justa e previa indenizacao em dinheiro nas desapropriacoes, com as ressalvas legais aplicaveis.', 'medium', 'Intervencao do Estado na propriedade privada', 'multiple_choice', 'published', 5155, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-087', 'O processo administrativo, nos termos da Lei n. 9.784/99, deve observar, entre outros, o principio da:', '["Celeridade, com decisao no menor tempo possivel, sem contraditorio.","Publicidade, com motivacao e contraditorio, quando couber.","Sigilo absoluto dos autos.","Irreformabilidade das decisoes administrativas.","Inexistencia de recurso."]'::jsonb, 1, 'O processo administrativo federal exige motivacao, contraditorio e ampla defesa quando houver sancao, alem de publicidade dos atos.', 'medium', 'Processo administrativo', 'multiple_choice', 'published', 5156, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-088', 'O controle externo da administracao publica e exercido, em regra, por:', '["Apenas pelo Poder Executivo.","Pelo Tribunal de Contas, com auxilio do sistema de controle interno.","Exclusivamente pelo Poder Judiciario.","Pelo Congresso Nacional, sem auxilio tecnico.","Pelo Ministerio Publico, de forma exclusiva."]'::jsonb, 1, 'A Constituicao atribui ao Tribunal de Contas a fiscalizacao contabil, financeira e orcamentaria, com apoio do controle interno.', 'medium', 'Controle da administracao', 'multiple_choice', 'published', 5157, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-089', 'O Sistema Nacional de Unidades de Conservacao (Lei n. 9.985/2000) divide as unidades em dois grupos principais:', '["Unidades de protecao integral e unidades de uso sustentavel.","Unidades federais e estaduais.","Unidades urbanas e rurais.","Unidades publicas e privadas.","Unidades temporarias e permanentes."]'::jsonb, 0, 'O SNUC classifica as unidades de conservacao em unidades de protecao integral e unidades de uso sustentavel.', 'medium', 'Sistema Nacional das Unidades de Conservacao (Lei n. 9.985/2000)', 'multiple_choice', 'published', 5158, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-090', 'O Novo Codigo Florestal (Lei n. 12.651/2012) estabelece, entre outras figuras, a:', '["Reserva Legal, area obrigatoria de preservacao da vegetacao nativa na propriedade.","Exclusao total de areas de preservacao permanente.","Imunidade tributaria rural.","Desapropriacao automatica de terras.","Dispensa de licenciamento ambiental."]'::jsonb, 0, 'A Reserva Legal e percentual da propriedade rural que deve ser mantido com cobertura vegetal nativa, conforme a lei.', 'medium', 'Novo Codigo Florestal (Lei n. 12.651/2012)', 'multiple_choice', 'published', 5159, 'FCC', 'Area fiscal'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-091', 'A Lei de Politica Nacional dos Residuos Solidos (Lei n. 12.305/2011) institui, entre outros instrumentos, a:', '["Logistica reversa, com retorno dos produtos apos o uso pelo consumidor.","Isencao de taxas para aterros sanitarios.","Privatizacao de todos os servicos de limpeza.","Impossibilidade de reciclagem.","Dispensa de licenciamento para incineracao."]'::jsonb, 0, 'A PNRS prevê a logística reversa, mediante a qual fabricantes, importadores e distribuidores devem recolher e destinar adequadamente os residuos.', 'medium', 'Lei de Politica Nacional dos Residuos Solidos (Lei n. 12.305/2011)', 'multiple_choice', 'published', 5160, 'VUNESP', 'Area fiscal'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-092', 'A Lei dos Crimes Ambientais (Lei n. 9.605/98) prevê, entre outras sancoes, a:', '["Pena de morte para crimes graves.","Detracao automatica de todas as penas.","Possibilidade de penas restritivas de direitos e prestacao de servicos a comunidade.","Inimputabilidade de pessoas juridicas em qualquer hipotese.","Isencao de responsabilidade de dirigentes."]'::jsonb, 2, 'A Lei n. 9.605/98 prevê penas privativas de liberdade, restritivas de direitos e multa, alem de responsabilidade de pessoas juridicas nos casos legais.', 'medium', 'Lei dos Crimes Ambientais e Sancoes Administrativas (Lei n. 9.605/98)', 'multiple_choice', 'published', 5161, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-093', 'A Politica Nacional dos Recursos Hidricos (Lei n. 9.433/97) estabelece como instrumento de gestao:', '["A privatizacao irrestrita dos rios.","O outorga de direitos de uso da agua e a cobranca pelo uso, entre outros.","A dispensa de licenciamento para barragens.","A nacionalizacao de nascentes.","A extincao de comites de bacia."]'::jsonb, 1, 'A Lei n. 9.433/97 institui instrumentos como outorga, cobranca pelo uso da agua, enquadramento e planos de recursos hidricos.', 'medium', 'Politica Nacional dos Recursos Hidricos (Lei n. 9.433/97)', 'multiple_choice', 'published', 5162, 'CEBRASPE', 'Area fiscal'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-094', 'No processo civil, a prova documental deve ser apresentada, em regra:', '["Apenas em audiencia de instrucao.","Conforme os prazos e formas previstos no CPC, respeitado o contraditorio.","Sem necessidade de autenticacao em qualquer caso.","Exclusivamente por meio de copias simples.","Apenas pelo reu."]'::jsonb, 1, 'O CPC regula a producao e a juntada de documentos, exigindo respeito ao contraditorio e as formas legais de autenticacao.', 'medium', 'Prova', 'multiple_choice', 'published', 5163, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-095', 'Nas obrigacoes, a modalidade especial de pagamento que permite ao devedor pagar em coisa diversa da prevista, com anuencia do credor, e a:', '["Dacao em pagamento.","Compensacao legal automatica.","Novacao sem acordo.","Remissao tacita.","Sub-rogacao."]'::jsonb, 0, 'A dacao em pagamento consiste na entrega de coisa diversa da devida, mediante acordo entre as partes.', 'medium', 'Modalidades especiais de pagamento', 'multiple_choice', 'published', 5164, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-096', 'Os vicios redibitorios podem dar ao comprador, em regra:', '["Apenas o direito de retencao do preco.","A opcao entre a redibicao (resolucao) e o abatimento do preco, conforme o caso.","A obrigacao de manter o bem defeituoso.","A perda do direito de reclamar.","A condenacao criminal do vendedor."]'::jsonb, 1, 'O Codigo Civil assegura ao comprador, em caso de vicio redibitorio, a escolha entre a redibicao e o abatimento proporcional do preco.', 'medium', 'Vicios redibitorios e eviccao', 'multiple_choice', 'published', 5165, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-097', 'O parentesco por afinidade decorre de:', '["Vinculo de sangue entre pessoas.","Casamento ou uniao estavel, gerando relacao entre um conjuge e os parentes do outro.","Adocao, em qualquer hipotese.","Tutela judicial.","Contrato de sociedade."]'::jsonb, 1, 'O parentesco por afinidade nasce do casamento ou da uniao estavel, vinculando um conjuge aos parentes do outro.', 'easy', 'Parentesco', 'multiple_choice', 'published', 5166, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-098', 'A sucessao testamentaria permite ao testador dispor de parte de seus bens, observado o limite da:', '["Legitima, reservada aos herdeiros necessarios.","Totalidade do patrimonio, sem restricoes.","Metade do patrimonio, em qualquer caso.","Terca parte, sempre.","Quarta parte, apenas."]'::jsonb, 0, 'O testador pode dispor livremente da parcela disponivel; a legitima e reservada aos herdeiros necessarios.', 'medium', 'Sucessao testamentaria', 'multiple_choice', 'published', 5167, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-099', 'O registro imobiliario tem por finalidade, entre outras:', '["Criar direitos reais sem necessidade de titulo.","Dar publicidade e seguranca juridica aos negocios imobiliarios.","Substituir o contrato de compra e venda.","Isentar tributos sobre imoveis.","Garantir posse automatica."]'::jsonb, 1, 'O registro imobiliario confere publicidade e seguranca juridica, permitindo oposição a terceiros conforme a lei.', 'medium', 'Direito registral', 'multiple_choice', 'published', 5168, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-100', 'A posse, no Codigo Civil, pode ser adquirida por:', '["Apenas por compra e venda.","Fatos que demonstrem o exercicio, em nome proprio, de poderes inerentes a propriedade.","Somente por heranca.","Apenas por decisao judicial.","Por mera intencao, sem exercicio."]'::jsonb, 1, 'A posse se adquire por fatos que demonstrem o exercicio, em nome proprio, dos poderes inerentes a propriedade.', 'medium', 'Posse', 'multiple_choice', 'published', 5169, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-101', 'O condominio edilicio, em regra, exige:', '["Apenas acordo verbal entre os condôminos.","Convencao de condominio e regimento interno, conforme a lei.","Dispensa de assembleia.","Inexistencia de sindico.","Propriedade exclusiva das areas comuns."]'::jsonb, 1, 'O condominio edilicio e regido por convencao e regimento interno, com assembleia e sindico, conforme o Codigo Civil.', 'medium', 'Condominio', 'multiple_choice', 'published', 5170, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-102', 'Os direitos reais em garantia, como a hipoteca, tem por finalidade:', '["Transferir a propriedade ao credor.","Garantir o credito com vinculacao de bem, sem transferencia da propriedade.","Extinguir a divida automaticamente.","Substituir o contrato de mutuo.","Conferir posse ao credor."]'::jsonb, 1, 'A hipoteca e garantia real que vincula bem ao credito sem transferir a propriedade ao credor.', 'medium', 'Direitos reais em garantia', 'multiple_choice', 'published', 5171, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-103', 'No regime de bens entre conjuges, a comunhao parcial de bens compreende, em regra:', '["Todos os bens anteriores e posteriores ao casamento.","Apenas os bens adquiridos onerosamente na constancia do casamento.","Somente os bens do marido.","Bens doados a um dos conjuges.","Bens herdados antes do casamento."]'::jsonb, 1, 'Na comunhao parcial, comunicam-se os bens adquiridos onerosamente durante o casamento.', 'medium', 'Regime de bens entre os conjuges', 'multiple_choice', 'published', 5172, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-104', 'Os alimentos podem ser fixados judicialmente com base no:', '["Binomio necessidade-possibilidade, conforme o caso concreto.","Salario minimo, sempre.","Patrimonio do alimentando, apenas.","Vontade do alimentante, exclusivamente.","Idade dos filhos, apenas."]'::jsonb, 0, 'A fixacao dos alimentos considera as necessidades do alimentando e as possibilidades do alimentante.', 'medium', 'Alimentos', 'multiple_choice', 'published', 5173, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-105', 'O bem de familia legal e impenhoravel, em regra, para:', '["Todas as dividas, sem excecao.","Dividas comuns do casal ou da entidade familiar, ressalvadas as excecoes legais.","Apenas dividas fiscais.","Dividas trabalhistas do empregador.","Dividas contratuais de empresa."]'::jsonb, 1, 'O bem de familia legal e impenhoravel para dividas comuns, com as excecoes previstas em lei.', 'medium', 'Bem de familia', 'multiple_choice', 'published', 5174, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-106', 'A tutela e a curatela destinam-se, em regra, a:', '["Pessoas plenamente capazes.","Pessoas com capacidade reduzida ou incapazes, conforme o caso.","Apenas menores de 16 anos.","Somente idosos acima de 80 anos.","Exclusivamente empresas."]'::jsonb, 1, 'A tutela e a curatela protegem pessoas com capacidade reduzida ou incapazes, conforme o Codigo Civil.', 'medium', 'Tutela e curatela', 'multiple_choice', 'published', 5175, 'FCC', 'Tribunais')
